{"file_path":"sales_dashboard/loader.py","content":""""Load and prepare customer-session analytics data."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        if not line.strip() or line.lstrip().startswith("#"):
            continue

        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, flag = (field.strip() for field in fields)
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if flag == "1":
            converted = True
        elif flag == "0":
            converted = False
        elif flag == "":
            converted = None
        else:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "converted": converted})
    return out


def dedupe_sessions(events):
    """Keep the last session for each id and sort by day, then id."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions on every day in the inclusive range."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day - start_day] += 1
    return counts
